#[cfg(test)]
mod tests {
    use super::*;

    fn env(pairs: &[(&str, f64)]) -> HashMap<String, f64> {
        pairs.iter().map(|(k, v)| (k.to_string(), *v)).collect()
    }

    #[test]
    fn display_and_eval() {
        let e = mul(add(num(1.0), num(2.0)), var("x"));
        assert_eq!(e.to_string(), "((1 + 2) * x)");
        assert_eq!(e.eval(&env(&[("x", 4.0)])), Ok(12.0));
        assert_eq!(neg(sub(var("a"), num(0.5))).to_string(), "(-(a - 0.5))");
    }

    #[test]
    fn eval_errors() {
        let e = div(num(1.0), sub(var("y"), var("y")));
        assert_eq!(e.eval(&env(&[("y", 3.0)])), Err("division by zero".to_string()));
        assert_eq!(var("z").eval(&env(&[])), Err("unknown variable: z".to_string()));
    }

    #[test]
    fn simplify_rules() {
        let e = mul(add(num(1.0), num(2.0)), var("x"));
        assert_eq!(e.simplify().to_string(), "(3 * x)");
        assert_eq!(add(var("x"), num(0.0)).simplify(), var("x"));
        assert_eq!(mul(num(1.0), var("y")).simplify(), var("y"));
        assert_eq!(mul(var("y"), num(0.0)).simplify(), num(0.0));
        assert_eq!(neg(num(2.0)).simplify(), num(-2.0));
    }

    #[test]
    fn simplify_nested_and_keeps_div_by_zero() {
        let e = add(mul(var("x"), sub(num(3.0), num(2.0))), mul(num(0.0), var("q")));
        assert_eq!(e.simplify(), var("x"));
        let d = div(num(1.0), num(0.0));
        assert_eq!(d.clone().simplify(), d);
    }

    #[test]
    fn deep_tree() {
        let mut e = num(0.0);
        for i in 1..=1000 {
            e = add(e, num(i as f64));
        }
        assert_eq!(e.eval(&HashMap::new()), Ok(500500.0));
    }
}
